-- DIBUAT OTOMATIS oleh scripts/generate-seed.ts — jangan diedit manual.
begin;
on conflict (id) do update set code = excluded.code, name = excluded.name, title = excluded.title;
on conflict (id) do update set title = excluded.title;
on conflict (id) do update set name = excluded.name, description = excluded.description, optional = excluded.optional;
on conflict (id) do nothing;
delete from public.quiz_questions where quiz_id in ('pretest', 'posttest', 'mission-1', 'mission-2', 'mission-3', 'mission-4', 'mission-5', 'mission-6', 'mission-7', 'bank');
commit;
